"""Regenerate agent-data/design-md/INDEX.md from the vendored DESIGN.md corpus.

Reads each <brand>/DESIGN.md frontmatter (name + description), groups brands by
the upstream category map, and writes a chooser table. Run from anywhere:

    python .github/skills/design_taste/scripts/build_designmd_index.py
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[4]
CORPUS = REPO / "agent-data" / "design-md"

# Upstream README's grouping. New brands not listed here land in "Uncategorized"
# until a category is added.
CATEGORIES = {
    "AI & LLM platforms": [
        "claude", "cohere", "elevenlabs", "minimax", "mistral.ai", "ollama",
        "opencode.ai", "replicate", "runwayml", "together.ai", "voltagent", "x.ai",
    ],
    "Developer tools & IDEs": [
        "cursor", "expo", "lovable", "raycast", "superhuman", "vercel", "warp",
    ],
    "Backend, database & DevOps": [
        "clickhouse", "composio", "hashicorp", "mongodb", "posthog", "sanity",
        "sentry", "supabase",
    ],
    "Productivity & SaaS": [
        "cal", "intercom", "linear.app", "mintlify", "notion", "resend",
        "slack", "zapier",
    ],
    "Design & creative tools": [
        "airtable", "clay", "figma", "framer", "miro", "webflow",
    ],
    "Fintech & crypto": [
        "binance", "coinbase", "kraken", "mastercard", "revolut", "stripe", "wise",
    ],
    "E-commerce & retail": [
        "airbnb", "meta", "nike", "shopify", "starbucks",
    ],
    "Media & consumer tech": [
        "apple", "hp", "ibm", "nvidia", "pinterest", "playstation", "spacex",
        "spotify", "theverge", "uber", "vodafone", "wired",
    ],
    "Automotive": [
        "bmw", "bmw-m", "bugatti", "ferrari", "lamborghini", "renault", "tesla",
    ],
    "Retro web (period-accurate nostalgia)": [
        "dell-1996", "nintendo-2001",
    ],
}


def frontmatter(path: Path) -> dict[str, str]:
    """Minimal frontmatter reader: top-level `key: value` scalars only."""
    text = path.read_text(encoding="utf-8", errors="replace")
    m = re.match(r"\A---\s*\n(.*?)\n---\s*\n", text, re.DOTALL)
    if not m:
        return {}
    out: dict[str, str] = {}
    block = m.group(1)
    for key in ("name", "description"):
        km = re.search(rf"^{key}:\s*(.+?)(?=^\w[\w-]*:|\Z)", block, re.MULTILINE | re.DOTALL)
        if km:
            val = km.group(1).strip()
            val = re.sub(r"^[|>]-?\s*", "", val)  # YAML block-scalar marker
            val = re.sub(r"\s+", " ", val)
            if len(val) >= 2 and val[0] == val[-1] and val[0] in "\"'":
                val = val[1:-1]
            out[key] = val
    return out


def first_sentence(text: str, cap: int = 220) -> str:
    m = re.match(r"(.+?\.)\s", text + " ")
    s = m.group(1) if m else text
    if len(s) > cap:
        s = s[: cap - 1].rstrip() + "…"
    return s


def main() -> int:
    brands = sorted(p.parent.name for p in CORPUS.glob("*/DESIGN.md"))
    if not brands:
        print(f"no DESIGN.md found under {CORPUS}", file=sys.stderr)
        return 1
    by_cat: dict[str, list[str]] = {c: [] for c in CATEGORIES}
    by_cat["Uncategorized"] = []
    catmap = {b: c for c, bs in CATEGORIES.items() for b in bs}
    for b in brands:
        by_cat.setdefault(catmap.get(b, "Uncategorized"), by_cat["Uncategorized"])
        by_cat[catmap.get(b, "Uncategorized")].append(b)

    lines = [
        "<!-- GENERATED by .github/skills/design_taste/scripts/build_designmd_index.py — do not hand-edit. -->",
        "",
        "# Brand DESIGN.md Index",
        "",
        f"{len(brands)} brand design-language files. Each is a Stitch-format DESIGN.md:",
        "YAML frontmatter with measured color/typography tokens, then prose rules.",
        "Use them to calibrate a design *direction* (\"Linear-clean\", \"Apple-y\"),",
        "never to clone a real brand's identity onto a client site.",
        "",
        "Read one with: `agent-data/design-md/<brand>/DESIGN.md`",
        "",
    ]
    for cat, bs in by_cat.items():
        if not bs:
            continue
        lines += [f"## {cat}", "", "| Brand | Feel |", "|---|---|"]
        for b in bs:
            fm = frontmatter(CORPUS / b / "DESIGN.md")
            feel = first_sentence(fm.get("description", "")) or "(no description)"
            lines.append(f"| [`{b}`]({b}/DESIGN.md) | {feel} |")
        lines.append("")
    (CORPUS / "INDEX.md").write_text("\n".join(lines), encoding="utf-8", newline="\n")
    print(f"wrote {CORPUS / 'INDEX.md'} ({len(brands)} brands)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
